-- =============================================================================
-- 434 — LE CAHIER D'EXERCICES DE 3E (partie 4)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 434 --niveau 3e --matieres physique-chimie --suffixe 4 > supabase/contenu/434_exercices_3e_4.sql
--
-- 93 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   physique-chimie.k019    33 exercices · 11 chapitres
--   physique-chimie.k020    33 exercices · 11 chapitres
--   physique-chimie.k021    27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('f92c560e-6d8f-509d-b902-28417486a187'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le sac du randonneur","competence":"calculer","situation":"Trois amis partent en randonnée en montagne. On s’intéresse à l’énergie de ce qui les entoure et à celle qu’ils gagnent en montant.","documents":[{"id":"sit","type":"tableau","titre":"Dans la vallée","colonnes":["Situation","Ce qu’on observe"],"lignes":[["Le lac de barrage","Une grande masse d’eau retenue à 2 000 m d’altitude"],["Le skieur","Il descend la piste à grande vitesse"],["La barre de céréales","Elle est dans le sac à dos"],["La lampe frontale","Son boîtier chauffe après une heure"]],"enteteLignes":true,"source":"Situations imaginées pour l’exercice"}],"questions":[{"enonce":"Associe chaque situation à la forme d’énergie qu’elle illustre.","aide":"Pense à ce qui fait « agir » chaque objet : la hauteur, le mouvement, les aliments, la chaleur.","type":"association","gauche":[{"id":"g0","texte":"Le lac de barrage"},{"id":"g1","texte":"Le skieur"},{"id":"g2","texte":"La barre de céréales"},{"id":"g3","texte":"Le boîtier de la lampe"}],"droite":[{"id":"d0","texte":"De position"},{"id":"d1","texte":"Chimique"},{"id":"d2","texte":"Cinétique"},{"id":"d3","texte":"Thermique"}]},{"enonce":"Un randonneur de 60 kg monte de 300 m. Calcule son gain d’énergie de position Epp = m × g × h, avec g = 10 N/kg.","aide":"Multiplie 60 kg par 10 N/kg, puis par 300 m.","type":"nombre","unite":"J"},{"enonce":"Exprime ce gain en kilojoules (1 kJ = 1 000 J).","aide":"Divise par 1 000.","type":"nombre","unite":"kJ"},{"enonce":"Le pétrole est…","aide":"Une source est ce d’où l’on tire l’énergie ; une forme est la manière dont elle se présente.","type":"choix","options":[{"id":"a","texte":"une forme d’énergie renouvelable, produite par le Soleil"},{"id":"b","texte":"une source d’énergie renouvelable, qui ne s’épuise jamais"},{"id":"c","texte":"une source d’énergie, qui contient de l’énergie chimique"},{"id":"d","texte":"une forme d’énergie cinétique, liée à sa vitesse d’écoulement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"Le lac est en altitude : énergie **de position**. Le skieur est en mouvement : **cinétique**. La barre de céréales contient de l’énergie **chimique**. Un boîtier qui chauffe a de l’énergie **thermique**."},{"cle":{"type":"nombre","valeur":180000,"tolerance":0},"affichage":"180 000 J","explication":"Epp = 60 × 10 × 300 = **180 000 J**."},{"cle":{"type":"nombre","valeur":180,"tolerance":0},"affichage":"180 kJ","explication":"180 000 ÷ 1 000 = **180 kJ**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le pétrole est une **source** d’énergie non renouvelable ; l’énergie qu’il contient est de l’énergie **chimique**."}]$ex$::jsonb),
  ('f92c560e-6d8f-509d-b902-28417486a187'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La facture d’énergie de la famille Lopez","competence":"resoudre","situation":"La famille Lopez relève la consommation de ses appareils sur une semaine. Elle veut comprendre les unités et savoir d’où vient l’énergie qu’elle utilise.","documents":[{"id":"releve","type":"fiche","modele":"ticket","entete":"Relevé de la semaine","sousTitre":"Famille Lopez","emoji":"🔌","lignes":[{"texte":"Four électrique","valeur":"2,5 kWh","id":"z1"},{"texte":"Radiateur","valeur":"4 kWh","id":"z2"},{"texte":"Lave-linge","valeur":"1,2 kWh","id":"z3"},{"separateur":true},{"texte":"Consommation relevée","valeur":"?","gras":true}],"pied":"Valeurs inventées pour l’exercice"}],"questions":[{"enonce":"Touche la ligne de l’appareil qui a consommé le plus d’énergie.","aide":"Compare les valeurs en kWh.","type":"zone","document":"releve","multiple":false},{"enonce":"Quelle énergie totale la famille a-t-elle consommée ?","aide":"Additionne les trois consommations.","type":"nombre","unite":"kWh"},{"enonce":"Le four a consommé 2,5 kWh. Exprime cette énergie en millions de joules (1 kWh = 3,6 × 10⁶ J).","aide":"Multiplie 2,5 par 3,6.","type":"nombre","unite":"MJ"},{"enonce":"Classe ces sources d’énergie.","aide":"Une source renouvelable se reconstitue à l’échelle humaine.","type":"categories","categories":[{"id":"c0","texte":"Renouvelables"},{"id":"c1","texte":"Non renouvelables"}],"items":[{"id":"i0","texte":"Le vent"},{"id":"i1","texte":"Le charbon"},{"id":"i2","texte":"Le gaz"},{"id":"i3","texte":"La géothermie"},{"id":"i4","texte":"L’uranium"},{"id":"i5","texte":"Le soleil"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **radiateur** a consommé 4 kWh, plus que le four (2,5 kWh) et le lave-linge (1,2 kWh)."},{"cle":{"type":"nombre","valeur":7.7,"tolerance":0},"affichage":"7,7 kWh","explication":"2,5 + 4 + 1,2 = **7,7 kWh**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 MJ","explication":"2,5 × 3,6 = 9, donc **9 × 10⁶ J**, soit 9 millions de joules."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Vent, soleil et géothermie se renouvellent. Charbon, gaz et **uranium** ont des réserves limitées."}]$ex$::jsonb),
  ('f92c560e-6d8f-509d-b902-28417486a187'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois randonneurs, une même montée","competence":"raisonner","situation":"Léa, Hugo et Sam gravissent chacun une côte différente. On compare leur énergie de position en haut, avec g = 10 N/kg.","documents":[{"id":"rando","type":"tableau","titre":"Les trois randonneurs","colonnes":["Randonneur","Masse","Hauteur gravie"],"lignes":[["Léa","50 kg","400 m"],["Hugo","70 kg","300 m"],["Sam","80 kg","250 m"]],"enteteLignes":true,"source":"Valeurs inventées pour l’exercice"}],"questions":[{"enonce":"Calcule l’énergie de position gagnée par Léa (Epp = m × g × h).","aide":"50 × 10 × 400.","type":"nombre","unite":"J"},{"enonce":"Calcule celle de Hugo.","aide":"70 × 10 × 300.","type":"nombre","unite":"J"},{"enonce":"Qui a gagné le plus d’énergie de position ?","aide":"Calcule aussi celle de Sam avant de comparer : 80 × 10 × 250.","type":"choix","options":[{"id":"a","texte":"Léa, car elle monte le plus haut"},{"id":"b","texte":"Sam, car il est le plus lourd"},{"id":"c","texte":"Les trois ont gagné la même énergie"},{"id":"d","texte":"Hugo"}],"multiple":false},{"enonce":"Hugo monte avec un sac de 10 kg en plus (masse totale 80 kg). Quelle est alors son énergie de position ?","aide":"Remplace 70 kg par 80 kg.","type":"nombre","unite":"J"},{"enonce":"Léa monterait deux fois plus haut. Par combien son énergie de position serait-elle multipliée ?","aide":"Epp est proportionnelle à h.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":200000,"tolerance":0},"affichage":"200 000 J","explication":"Epp = 50 × 10 × 400 = **200 000 J**."},{"cle":{"type":"nombre","valeur":210000,"tolerance":0},"affichage":"210 000 J","explication":"Epp = 70 × 10 × 300 = **210 000 J**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Sam gagne 200 000 J, Léa 200 000 J, Hugo **210 000 J** : le plus haut ni le plus lourd ne gagne forcément le plus, il faut multiplier masse et hauteur."},{"cle":{"type":"nombre","valeur":240000,"tolerance":0},"affichage":"240 000 J","explication":"Epp = 80 × 10 × 300 = **240 000 J**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Epp = m × g × h est proportionnelle à h : doubler la hauteur **double** l’énergie."}]$ex$::jsonb),
  ('d5ca2d31-c8e0-5449-b11f-8e16aae8e631'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La lampe de poche","competence":"observer-schema","situation":"Dans une lampe de poche, une pile alimente une ampoule. On schématise ce que devient l’énergie.","documents":[{"id":"chaine","type":"chaine","disposition":"ligne","titre":"Chaîne énergétique d’une lampe de poche","noeuds":[{"id":"z1","texte":"Pile","emoji":"🔋"},{"id":"z2","texte":"Lampe","emoji":"💡"},{"id":"z3","texte":"Lumière","emoji":"✨"}],"liens":[{"de":"z1","a":"z2","texte":"énergie ?"},{"de":"z2","a":"z3"}]}],"questions":[{"enonce":"Touche l’élément qui convertit l’énergie, le convertisseur.","aide":"Le convertisseur est l’appareil placé entre la source et l’utilisation.","type":"zone","document":"chaine","multiple":false},{"enonce":"Quelle forme d’énergie la pile stocke-t-elle ?","aide":"La pile contient des substances chimiques.","type":"choix","options":[{"id":"a","texte":"Thermique"},{"id":"b","texte":"Cinétique"},{"id":"c","texte":"De position"},{"id":"d","texte":"Chimique"}],"multiple":false},{"enonce":"Complète la conversion réalisée par la lampe.","aide":"La lampe brille et chauffe.","type":"trous","segments":["Dans la lampe, l’énergie ",0," est convertie en énergie utile ",1," et en énergie perdue ",2,"."],"banque":["cinétique","chimique","lumineuse","thermique","électrique","nucléaire"]},{"enonce":"Associe chaque convertisseur à sa conversion.","aide":"Regarde la forme d’énergie d’entrée et celle de sortie.","type":"association","gauche":[{"id":"g0","texte":"Panneau photovoltaïque"},{"id":"g1","texte":"Alternateur"},{"id":"g2","texte":"Pile"},{"id":"g3","texte":"Chaudière"}],"droite":[{"id":"d0","texte":"Chimique → électrique"},{"id":"d1","texte":"Chimique → thermique"},{"id":"d2","texte":"Cinétique → électrique"},{"id":"d3","texte":"Lumineuse → électrique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **lampe** change la forme de l’énergie : c’est le convertisseur."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une pile stocke de l’énergie **chimique**."},{"cle":{"type":"trous","trous":[["electrique"],["lumineuse"],["thermique"]]},"affichage":"électrique · lumineuse · thermique","explication":"Énergie **électrique** → énergie utile **lumineuse**, avec des pertes **thermiques** : l’ampoule chauffe."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"Le panneau reçoit de la lumière, l’alternateur un mouvement, la pile des réactifs chimiques, la chaudière un combustible."}]$ex$::jsonb),
  ('d5ca2d31-c8e0-5449-b11f-8e16aae8e631'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un radiateur dans le salon","competence":"observer-schema","situation":"Un radiateur chauffe la pièce. L’air circule le long des murs, et l’énergie se transfère de trois façons différentes.","documents":[{"id":"piece","type":"schema","titre":"La pièce chauffée","largeur":320,"hauteur":230,"elements":[{"forme":"rect","x":20,"y":20,"l":280,"h":180,"teinte":"gris","motif":"aucun"},{"forme":"rect","x":30,"y":110,"l":26,"h":80,"teinte":"brun","motif":"clair"},{"forme":"texte","x":43,"y":215,"texte":"Radiateur","taille":"petit","ancre":"milieu"},{"forme":"ligne","de":[80,180],"a":[80,50],"fleche":"fin","id":"z1","zone":true},{"forme":"ligne","de":[250,50],"a":[250,180],"fleche":"fin","id":"z2","zone":true},{"forme":"ligne","de":[240,190],"a":[90,190],"fleche":"fin","id":"z3","zone":true},{"forme":"texte","x":250,"y":215,"texte":"Fenêtre","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Touche la flèche qui montre l’air chaud près du radiateur.","aide":"L’air chaud s’élève.","type":"zone","document":"piece","multiple":false},{"enonce":"Associe chaque situation à son mode de transfert thermique.","aide":"Solide, fluide en mouvement, vide : trois mécanismes.","type":"association","gauche":[{"id":"g0","texte":"Une cuillère chauffe dans la casserole"},{"id":"g1","texte":"L’air chaud monte au-dessus du radiateur"},{"id":"g2","texte":"La chaleur du Soleil traverse le vide"}],"droite":[{"id":"d0","texte":"Convection"},{"id":"d1","texte":"Rayonnement"},{"id":"d2","texte":"Conduction"}]},{"enonce":"Un pull en laine garde au chaud parce que la laine…","aide":"Pense aux isolants : laine, air immobile, polystyrène.","type":"choix","options":[{"id":"a","texte":"est un isolant thermique, qui ralentit la perte de chaleur"},{"id":"b","texte":"est un très bon conducteur thermique, qui évacue la chaleur"},{"id":"c","texte":"ajoute de l’énergie au corps en lui transmettant la sienne"},{"id":"d","texte":"produit elle-même de la chaleur en se frottant à la peau"}],"multiple":false},{"enonce":"Une boisson chaude refroidit dans une tasse. Où va la chaleur ?","aide":"La chaleur ne va jamais spontanément du froid vers le chaud.","type":"choix","options":[{"id":"a","texte":"De la boisson vers l’air plus froid"},{"id":"b","texte":"De l’air vers la boisson"},{"id":"c","texte":"Elle passe dans les deux sens sans aucune perte"},{"id":"d","texte":"Elle reste dans la boisson"}],"multiple":false}]}$ex$::jsonb,
