   $ex${"titre":"La DEL dans le bon sens","competence":"raisonner","situation":"Une DEL ne laisse passer le courant que dans un seul sens. Deux élèves ont monté le même circuit, mais l’une a retourné la DEL.","documents":[{"id":"un","type":"circuit","titre":"Circuit 1","branches":[{"de":[0,4],"a":[0,0],"composant":"pile","id":"z1"},{"de":[0,4],"a":[4,4]},{"de":[4,4],"a":[8,4],"composant":"resistance","nom":"R","id":"z2"},{"de":[8,4],"a":[8,0],"composant":"del","nom":"D","allume":true,"id":"z3"},{"de":[8,0],"a":[4,0]},{"de":[4,0],"a":[0,0]}]},{"id":"deux","type":"circuit","titre":"Circuit 2","branches":[{"de":[0,4],"a":[0,0],"composant":"pile","id":"z4"},{"de":[0,4],"a":[4,4]},{"de":[4,4],"a":[8,4],"composant":"resistance","nom":"R","id":"z5"},{"de":[8,0],"a":[8,4],"composant":"del","nom":"D","id":"z6"},{"de":[8,0],"a":[4,0]},{"de":[4,0],"a":[0,0]}]}],"questions":[{"enonce":"Dans le circuit 1, touche la DEL.","aide":"Le symbole ressemble à une diode avec des flèches.","type":"zone","document":"un","multiple":false},{"enonce":"Pourquoi la DEL du circuit 1 s’allume-t-elle ?","aide":"Une DEL laisse passer le courant dans un seul sens.","type":"choix","options":[{"id":"a","texte":"Le courant la traverse dans son sens passant, le bon sens"},{"id":"b","texte":"Le circuit est ouvert, le courant passe par l’air"},{"id":"c","texte":"La pile est plus puissante et fournit plus de tension"},{"id":"d","texte":"La résistance produit la lumière à la place de la DEL"}],"multiple":false},{"enonce":"Dans le circuit 2, la DEL s’allume.","aide":"Elle est retournée : le courant tente de la traverser à l’envers.","type":"choix","options":[{"id":"a","texte":"Vrai"},{"id":"b","texte":"Faux"}],"multiple":false},{"enonce":"Dans le circuit 1, dans le fil du haut, les électrons circulent…","aide":"Les électrons vont en sens inverse du courant conventionnel.","type":"choix","options":[{"id":"a","texte":"dans les deux sens à la fois"},{"id":"b","texte":"ils ne circulent pas"},{"id":"c","texte":"de la borne − de la pile vers la DEL"},{"id":"d","texte":"de la DEL vers la borne − de la pile"}],"multiple":false},{"enonce":"Complète.","aide":"Il n’y a plus de récepteur pour limiter le courant.","type":"trous","segments":["Un fil qui relie directement les deux bornes d’une pile crée un ",0," : l’intensité devient ",1," et les fils ",2,"."],"banque":["interrupteur","refroidissent","nulle","chauffent","court-circuit","énorme"]}]}$ex$::jsonb,
