   $ex${"titre":"Série ou dérivation ?","competence":"observer-schema","situation":"Deux montages alimentent chacun deux lampes avec la même pile. Tu dois les reconnaître et prévoir ce qui se passe si une lampe grille.","documents":[{"id":"sa","type":"circuit","titre":"Circuit A","branches":[{"de":[0,4],"a":[0,0],"composant":"pile"},{"de":[0,0],"a":[4,0],"composant":"lampe","nom":"L1","allume":true},{"de":[4,0],"a":[8,0],"composant":"lampe","nom":"L2","allume":true},{"de":[8,0],"a":[8,4]},{"de":[8,4],"a":[0,4]}]},{"id":"sb","type":"circuit","titre":"Circuit B","branches":[{"de":[0,4],"a":[0,0],"composant":"pile"},{"de":[0,0],"a":[4,0]},{"de":[4,0],"a":[8,0]},{"de":[0,4],"a":[4,4]},{"de":[4,4],"a":[8,4]},{"de":[4,0],"a":[4,4],"composant":"lampe","nom":"L1","allume":true},{"de":[8,0],"a":[8,4],"composant":"lampe","nom":"L2","allume":true}]}],"questions":[{"enonce":"Associe chaque circuit à son montage.","aide":"En série, le courant n’a qu’un seul chemin.","type":"association","gauche":[{"id":"g0","texte":"Circuit A"},{"id":"g1","texte":"Circuit B"}],"droite":[{"id":"d0","texte":"En dérivation"},{"id":"d1","texte":"En série"}]},{"enonce":"La lampe L1 du circuit A grille. Que devient L2 ?","aide":"La boucle est coupée.","type":"choix","options":[{"id":"a","texte":"Elle brille plus fort"},{"id":"b","texte":"Elle continue de briller"},{"id":"c","texte":"Elle s’éteint"},{"id":"d","texte":"Elle chauffe seulement"}],"multiple":false},{"enonce":"Complète.","aide":"Série et dérivation ont des lois opposées.","type":"trous","segments":["En série, l’intensité est ",0," partout ; en dérivation, la ",1," est la même dans chaque branche."],"banque":["nulle","intensité","tension","la même","double"]},{"enonce":"La lampe L1 du circuit B grille. Que devient L2 ?","aide":"Sa branche est indépendante.","type":"choix","options":[{"id":"a","texte":"Elle s’éteint, car le courant ne circule plus nulle part"},{"id":"b","texte":"Elle continue de briller, car elle a sa propre branche"},{"id":"